<?php
require_once 'config.php';require_login();$pageTitle='Data Siswa';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id_siswa']??0);$nis=trim($_POST['nis']??'');$nama=trim($_POST['nama_siswa']??'');$kelas=trim($_POST['kelas']??'');$jk=$_POST['jenis_kelamin']??'L';$alamat=trim($_POST['alamat']??'');if(!$nis||!$nama||!$kelas)$error='NIS, nama, dan kelas wajib diisi.';else{try{if($id){$st=$pdo->prepare('UPDATE siswa SET nis=?,nama_siswa=?,kelas=?,jenis_kelamin=?,alamat=? WHERE id_siswa=?');$st->execute([$nis,$nama,$kelas,$jk,$alamat,$id]);}else{$st=$pdo->prepare('INSERT INTO siswa(nis,nama_siswa,kelas,jenis_kelamin,alamat) VALUES(?,?,?,?,?)');$st->execute([$nis,$nama,$kelas,$jk,$alamat]);}header('Location: siswa.php?ok=1');exit;}catch(PDOException $e){$error='Gagal menyimpan. Pastikan NIS belum digunakan.';}}}if($action==='delete'&&is_admin()){try{$st=$pdo->prepare('DELETE FROM siswa WHERE id_siswa=?');$st->execute([(int)$_POST['id_siswa']]);header('Location: siswa.php?ok=1');exit;}catch(PDOException $e){$error='Siswa sudah memiliki catatan pelanggaran sehingga tidak dapat dihapus.';}}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM siswa WHERE id_siswa=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT * FROM siswa WHERE nis LIKE ? OR nama_siswa LIKE ? OR kelas LIKE ? ORDER BY nama_siswa');$like="%$q%";$st->execute([$like,$like,$like]);$rows=$st->fetchAll();include 'partials/header.php';?>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="alert success">Data berhasil diproses.</div><?php endif;?><div class="panel"><div class="panel-head"><div><h3><?=$edit?'Edit Siswa':'Tambah Siswa'?></h3><p>Lengkapi identitas siswa.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="action" value="save"><input type="hidden" name="id_siswa" value="<?=e($edit['id_siswa']??'')?>"><div><label>NIS *</label><input name="nis" required value="<?=e($edit['nis']??'')?>"></div><div><label>Nama Lengkap *</label><input name="nama_siswa" required value="<?=e($edit['nama_siswa']??'')?>"></div><div><label>Kelas *</label><input name="kelas" required placeholder="XII TKJ 1" value="<?=e($edit['kelas']??'')?>"></div><div><label>Jenis Kelamin</label><select name="jenis_kelamin"><option value="L" <?=($edit['jenis_kelamin']??'L')==='L'?'selected':''?>>Laki-laki</option><option value="P" <?=($edit['jenis_kelamin']??'')==='P'?'selected':''?>>Perempuan</option></select></div><div class="wide"><label>Alamat</label><textarea name="alamat" rows="2"><?=e($edit['alamat']??'')?></textarea></div><div class="wide"><button class="btn primary">Simpan</button> <?php if($edit):?><a class="btn" href="siswa.php">Batal</a><?php endif;?></div></form></div>
<div class="panel"><div class="panel-head"><div><h3>Daftar Siswa (<?=count($rows)?>)</h3></div><form class="search" method="get"><input name="q" placeholder="Cari nama, NIS, kelas" value="<?=e($q)?>"><button class="btn">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>NIS</th><th>Nama</th><th>Kelas</th><th>JK</th><th>Alamat</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nis'])?></td><td><b><?=e($r['nama_siswa'])?></b></td><td><?=e($r['kelas'])?></td><td><?=e($r['jenis_kelamin'])?></td><td><?=e($r['alamat'])?></td><td><a class="link" href="?edit=<?=$r['id_siswa']?>">Edit</a> <?php if(is_admin()):?><form class="inline" method="post" onsubmit="return confirm('Hapus siswa ini?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_siswa" value="<?=$r['id_siswa']?>"><button class="link red">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Belum ada data siswa.</td></tr><?php endif;?></tbody></table></div></div><?php include 'partials/footer.php';?>
